        letters = ["l"] * n
    elif isinstance(align, (str, list, tuple)):
        letters = list(align)
    else:
        raise ExportError("align must be text or a list of l and r")
    if len(letters) != n:
        raise ExportError("align has %d letters for %d columns" % (len(letters), n))
    for letter in letters:
        if letter not in ("l", "r") or not isinstance(letter, str):
            raise ExportError("align letters must be l or r, not %r" % (letter,))
    body = []
    for row in rows:
        cells = [_cell(c) for c in row]
        if len(cells) != n:
            raise ExportError("a row has %d cells for %d columns" % (len(cells), n))
        body.append(cells)
    widths = [len(t) for t in titles]
    for cells in body:
        for i, c in enumerate(cells):
            if len(c) > widths[i]:
                widths[i] = len(c)

    def line(cells):
        parts = []
