"""Command line: rates, budgets, recurring entries and reports."""
import functools
import re

from tallybook.accounts import valid_path
from tallybook.budgets import Budget, budget_status
from tallybook.cli.core import CliError, Opt, command, group_summary, parse_int
from tallybook.cli.render import (REPORT_KINDS, budget_lines_out, build_report, json_out,
                                  month_of, report_out, table_out)
from tallybook.dates import Period, format_date, parse_date
from tallybook.export import money_to_dict, transaction_to_dict
from tallybook.model import Posting, Transaction
from tallybook.money import Money, parse_amount
from tallybook.recurring import Recurring

_TAG = re.compile(r"[A-Za-z0-9][A-Za-z0-9_-]*")
_BLANKS = " \t"

group_summary("rate", "set | list | remove")
group_summary("budget", "add | list | remove | status")
group_summary("recurring", "add | list | remove | materialize")
group_summary("report", " | ".join(REPORT_KINDS))


def _guarded(handler):
    """Numbers too long for the interpreter are a wrong value (exit 1), never a crash."""

    @functools.wraps(handler)
    def run(ctx, args):
        try:
            return handler(ctx, args)
        except (ValueError, OverflowError) as err:
            raise CliError("invalid number: %s" % err)

    return run


def _day(text, default):
    return default if text is None else parse_date(text)


def _period(text):
    return None if text is None else Period.parse(text)


def parse_posting_arg(text):
    """One posting argument: ``ACCOUNT`` or ``ACCOUNT AMOUNT CURRENCY``, then ``; note``."""
    head, _semi, note = text.partition(";")
    note = note.strip(_BLANKS)
    if "\n" in note or "\r" in note:
        raise CliError("invalid posting '%s': a note cannot contain a line break" % text)
    words = [w for w in re.split("[ \t]+", head.strip(_BLANKS)) if w]
    if len(words) not in (1, 3):
        raise CliError("invalid posting '%s': write ACCOUNT or ACCOUNT AMOUNT CURRENCY" % text)
    path = words[0]
    if not valid_path(path):
        raise CliError("invalid posting '%s': invalid account path '%s'" % (text, path))
    if len(words) == 1:
        return Posting(path, None, note)
    cur = words[2]
    return Posting(path, Money(parse_amount(words[1], cur), cur), note)


# -- rates -----------------------------------------------------------------

@command("rate set", usage="rate set FROM TO RATE [--on DATE]",
         summary="record an exchange rate (one FROM buys RATE of TO)",
         opts=[Opt("on")], pos=[("FROM", "1"), ("TO", "1"), ("RATE", "1")])
@_guarded
def rate_set(ctx, args):
    src, dst, rate = args.pos
    on = _day(args.get("on"), ctx.today)
    store = ctx.open_book()
    store.set_rate(src, dst, rate, on)
    return "set 1 %s = %s %s on %s\n" % (src, rate, dst, format_date(on))


@command("rate list", usage="rate list [--json]", summary="list the exchange rates",
         opts=[Opt("json", "flag")])
@_guarded
def rate_list(ctx, args):
    rows = ctx.open_book().rate_rows()
    if args.flag("json"):
        return json_out([{"from": s, "to": d, "date": format_date(o), "rate": t}
                         for s, d, o, t in rows])
    return table_out(["From", "To", "Date", "Rate"],
                     [[s, d, format_date(o), t] for s, d, o, t in rows], "lllr")


@command("rate remove", usage="rate remove FROM TO [--on DATE]",
         summary="remove the rate set for a day",
         opts=[Opt("on")], pos=[("FROM", "1"), ("TO", "1")])
@_guarded
def rate_remove(ctx, args):
    src, dst = args.pos
    on = _day(args.get("on"), ctx.today)
    ctx.open_book().remove_rate(src, dst, on)
    return "removed rate %s -> %s on %s\n" % (src, dst, format_date(on))


# -- budgets ---------------------------------------------------------------

@command("budget add", usage="budget add PATTERN AMOUNT [--per KIND] [--start DATE]",
         summary="add a budget; KIND is month (default), quarter or year",
         opts=[Opt("per"), Opt("start")], pos=[("PATTERN", "1"), ("AMOUNT", "1")])
@_guarded
def budget_add(ctx, args):
    pattern, amount_text = args.pos
    kind = args.get("per", "month")
    start = _day(args.get("start"), ctx.today)
    budget = Budget(pattern, kind, Money.parse(amount_text), start)
    ctx.open_book().add_budget(budget)
    return "added budget %s %s per %s\n" % (pattern, budget.amount, kind)


@command("budget list", usage="budget list [--json]", summary="list the budgets",
         opts=[Opt("json", "flag")])
@_guarded
def budget_list(ctx, args):
    budgets = ctx.open_book().budgets()
    if args.flag("json"):
        return json_out([{"pattern": b.pattern, "period_kind": b.period_kind,
                          "amount": money_to_dict(b.amount), "start": format_date(b.start)}
                         for b in budgets])
    return table_out(["Pattern", "Per", "Amount", "Start"],
                     [[b.pattern, b.period_kind, str(b.amount), format_date(b.start)] for b in budgets],
                     "llrl")


@command("budget remove", usage="budget remove PATTERN [--per KIND]",
         summary="remove a budget (KIND defaults to month)",
         opts=[Opt("per")], pos=[("PATTERN", "1")])
@_guarded
def budget_remove(ctx, args):
    pattern = args.pos[0]
    kind = args.get("per", "month")
    ctx.open_book().remove_budget(pattern, kind)
    return "removed budget %s per %s\n" % (pattern, kind)


@command("budget status", usage="budget status [--period PERIOD] [--json]",
         summary="how the budgets are doing in a period (default: this month)",
         opts=[Opt("period"), Opt("json", "flag")])
@_guarded
def budget_status_cmd(ctx, args):
    period = _period(args.get("period"))
    if period is None:
        period = month_of(ctx.today)
    store = ctx.open_book()
    lines = budget_status(store.budgets(), store.ledger(), period)
    return budget_lines_out(lines, args.flag("json"))


# -- recurring -------------------------------------------------------------

def _template_dict(tx):
    return {"payee": tx.payee, "narration": tx.narration, "flag": tx.flag,
            "tags": sorted(set(tx.tags)),
            "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                         for p in tx.postings]}


def _check_template_text(what, text):
    if "\n" in text or "\r" in text:
        raise CliError("invalid %s: a line break is not allowed" % what)


@command("recurring add",
         usage=("recurring add NAME SCHEDULE PAYEE [--start DATE] [--end DATE] [--count N] "
                "[--narration TEXT] [--flag F] [--tag TAG]... [-p POSTING]..."),
         summary="add a recurring item with a transaction template",
         opts=[Opt("start"), Opt("end"), Opt("count"), Opt("narration"), Opt("flag"),
               Opt("tag", "repeat"), Opt("posting", "repeat", short="p")],
         pos=[("NAME", "1"), ("SCHEDULE", "1"), ("PAYEE", "1")])
@_guarded
def recurring_add(ctx, args):
    name, schedule, payee = args.pos
    start = _day(args.get("start"), ctx.today)
    end = _day(args.get("end"), None)
    count = None if args.get("count") is None else parse_int(args.get("count"), "count")
    narration = args.get("narration", "")
    flag = args.get("flag", "*")
    tags = args.many("tag")
    postings = [parse_posting_arg(t) for t in args.many("posting")]
    if flag not in ("*", "!"):
        raise CliError("invalid flag '%s': use * or !" % flag)
    for tag in tags:
        if not _TAG.fullmatch(tag):
            raise CliError("invalid tag '%s'" % tag)
    _check_template_text("payee", payee)
    _check_template_text("narration", narration)
    template = Transaction(start, payee, narration, postings, tuple(sorted(set(tags))), flag)
    rec = Recurring(name, schedule, template, start, end, count)
    ctx.open_book().add_recurring(rec)
    return "added recurring %s\n" % name


@command("recurring list", usage="recurring list [--json]", summary="list the recurring items",
         opts=[Opt("json", "flag")])
@_guarded
def recurring_list(ctx, args):
    store = ctx.open_book()
    items = [(rec, store.materialized_through(rec.name)) for rec in store.recurring()]
    if args.flag("json"):
        return json_out([{
            "name": r.name, "schedule": str(r.schedule), "start": format_date(r.start),
            "end": None if r.end is None else format_date(r.end), "count": r.count,
            "materialized_through": None if t is None else format_date(t),
            "template": _template_dict(r.template)} for r, t in items])
    rows = [[r.name, str(r.schedule), format_date(r.start),
             "" if r.end is None else format_date(r.end),
             "" if r.count is None else str(r.count),
             "" if t is None else format_date(t), r.template.payee] for r, t in items]
    return table_out(["Name", "Schedule", "Start", "End", "Count", "Through", "Payee"], rows, "lllllll")


@command("recurring remove", usage="recurring remove NAME", summary="remove a recurring item",
         pos=[("NAME", "1")])
@_guarded
def recurring_remove(ctx, args):
    ctx.open_book().remove_recurring(args.pos[0])
    return "removed recurring %s\n" % args.pos[0]


@command("recurring materialize", usage="recurring materialize [--upto DATE] [--json]",
         summary="turn the due occurrences into transactions (up to today or --upto)",
         opts=[Opt("upto"), Opt("json", "flag")])
@_guarded
def recurring_materialize(ctx, args):
    upto = _day(args.get("upto"), None)
    made = ctx.open_book().materialize(upto=upto, today=ctx.today)
    if args.flag("json"):
        return json_out([transaction_to_dict(t) for t in made])
    return "created %d transactions\n" % len(made)


# -- reports ---------------------------------------------------------------

def _report(kind, ctx, args, account=None):
    as_of = _day(args.get("as-of"), None)
    period = _period(args.get("period"))
    store = ctx.open_book()
    report = build_report(kind, store.ledger(), ctx.today, as_of=as_of, period=period,
                          convert=args.get("convert"), account=account, rollup=args.flag("rollup"))
    return report_out(report, args.flag("json"))


@command("report trial-balance", usage="report trial-balance [--as-of DATE] [--json]",
         summary="debits and credits of every account",
         opts=[Opt("as-of"), Opt("json", "flag")])
@_guarded
def report_trial_balance(ctx, args):
    return _report("trial-balance", ctx, args)


@command("report balance-sheet", usage="report balance-sheet [--as-of DATE] [--convert CUR] [--json]",
         summary="assets, liabilities and equity (default: as of today)",
         opts=[Opt("as-of"), Opt("convert"), Opt("json", "flag")])
@_guarded
def report_balance_sheet(ctx, args):
    return _report("balance-sheet", ctx, args)


@command("report income-statement",
         usage="report income-statement [--period PERIOD] [--convert CUR] [--json]",
         summary="income and expenses in a period (default: this month)",
         opts=[Opt("period"), Opt("convert"), Opt("json", "flag")])
@_guarded
def report_income_statement(ctx, args):
    return _report("income-statement", ctx, args)


@command("report cashflow", usage="report cashflow [--period PERIOD] [--json]",
         summary="money in and out of the asset accounts (default: this month)",
         opts=[Opt("period"), Opt("json", "flag")])
@_guarded
def report_cashflow(ctx, args):
    return _report("cashflow", ctx, args)


@command("report register", usage="report register ACCOUNT [--period PERIOD] [--rollup] [--json]",
         summary="the postings of one account with a running balance",
         opts=[Opt("period"), Opt("rollup", "flag"), Opt("json", "flag")],
         pos=[("ACCOUNT", "1")])
@_guarded
def report_register(ctx, args):
    return _report("register", ctx, args, account=args.pos[0])

